  const estimate = (cid, rate, basis, from, to) => { const days = daysBetween(from, to) + 1; return basis === 'DAY' ? rate * days : basis === 'MONTH' ? Math.round((rate * days) / 30) : rate * days * hoursPerDay(cid); };
  const projectOk = (actor, pid, sid, key) => {
    const problems = []; const pj = pid ? db.prepare('SELECT id, company_id FROM org_projects WHERE id = ? AND deleted_at IS NULL').get(rid(pid)) : null; if (!pj || pj.company_id !== actor.companyId) problems.push({ field: 'projectId', message: 'Choose a project of your company' });
    let st = null; if (sid) { st = db.prepare('SELECT id, org_project_id FROM org_sites WHERE id = ? AND deleted_at IS NULL').get(rid(sid)); if (!st || !pj || st.org_project_id !== pj.id) problems.push({ field: 'siteId', message: 'Choose a site of that project' }); }
    fail(problems); if (key && !may(actor, key, pj.id, st?.id ?? null)) throw forbidden(`You may not do this for that project or site (permission ${key}).`); return { pj, st };
  };

  // ---- availability across the fleet (FR-01, FR-06) ----------------------------------------------------------------------------------------------------------------------------------------------------
