  const clashes = (equipmentId, from, to, { excludeId = 0, takesOver = 0 } = {}) => db.prepare(`SELECT id, doc_no, from_date, to_date, org_project_id, status, phase FROM plt_allocations WHERE equipment_id = ? AND deleted_at IS NULL AND status IN ('SUBMITTED', 'APPROVED') AND phase <> 'RELEASED' AND id <> ? AND id <> ? AND NOT (to_date < ? OR from_date > ?) ORDER BY from_date`).all(equipmentId, excludeId, takesOver, from, to);
  function availability(actor, q = {}) {
    if (!holds(actor, 'plant.requisition.view') && !holds(actor, 'plant.allocation.view')) throw forbidden('You may not check the availability of equipment (permission plant.requisition.view).'); const from = q.fromDate ?? today(); const to = q.toDate ?? addDays(from, 30); if (to < from) fail([{ field: 'toDate', message: 'The period ends before it starts' }]);
    const rows = db.prepare(`SELECT * FROM plt_equipment WHERE company_id = ? AND deleted_at IS NULL AND approved_at IS NOT NULL AND equip_state <> 'DISPOSED' ${q.classItemId ? 'AND class_item_id = ?' : ''} ORDER BY asset_code LIMIT 300`).all(...[actor.companyId, ...(q.classItemId ? [rid(q.classItemId)] : [])]);
    const out = rows.map((e) => { const c = clashes(e.id, from, to, { excludeId: q.excludeAllocationId ?? 0, takesOver: q.takesOver ?? 0 }); const a = eqs.allocatable(actor, e.id, { date: from, planning: true, internal: true }); const certs = equipment.certsOf(e, from); const lapse = certs.items.filter((x) => x.validUntil && x.validUntil >= from && x.validUntil < to && x.mandatory).map((x) => ({ docType: x.docType, validUntil: x.validUntil }));
      const seeLoc = may(actor, 'plant.equipment.view', e.org_project_id, e.org_site_id);
      return { equipmentId: e.id, assetCode: e.asset_code, class: classLabel(e.class_item_id), make: e.make, model: e.model, capacity: e.capacity, ownership: e.ownership, state: e.equip_state, stateLabel: EQUIP_STATE[e.equip_state], project: seeLoc ? pcode(e.org_project_id) : null, site: seeLoc ? scode(e.org_site_id) : null, free: c.length === 0, conflict: c[0] ? { docNo: c[0].doc_no, from: c[0].from_date, to: c[0].to_date } : null, ready: a.allowed, problems: a.problems.map((p) => p.message), lapsesDuring: lapse, usable: c.length === 0 && a.allowed }; });
    return { fromDate: from, toDate: to, rows: out.sort((x, y) => Number(y.usable) - Number(x.usable) || x.assetCode.localeCompare(y.assetCode)), usable: out.filter((x) => x.usable).length };
  }

