  const rscope = (actor) => { const f = scopeOf(actor, 'plant.requisition.view', { project: 'x.org_project_id', site: 'x.org_site_id' }); return `x.company_id = :c AND ${f}`; };
  const rrow = (actor, id, key = 'plant.requisition.view') => { const r = db.prepare('SELECT * FROM plt_requisitions WHERE id = ? AND company_id = ? AND deleted_at IS NULL').get(rid(id), actor.companyId); if (!r || !may(actor, 'plant.requisition.view', r.org_project_id, r.org_site_id)) throw notFound('That requisition does not exist.'); if (key !== 'plant.requisition.view' && !may(actor, key, r.org_project_id, r.org_site_id)) throw forbidden(`You may not do this (permission ${key}).`); return r; };
