      return { classes: db.prepare("SELECT id, code, name FROM mdm_items WHERE company_id = ? AND deleted_at IS NULL AND item_status = 'ACTIVE' AND item_type = 'EQUIPMENT' ORDER BY code LIMIT 500").all(actor.companyId), projects: db.prepare("SELECT id, code, name FROM org_projects WHERE company_id = ? AND deleted_at IS NULL AND status = 'ACTIVE' ORDER BY code").all(actor.companyId).filter((p) => okp(p.id)),
        sites: db.prepare("SELECT s.id, s.code, s.name, s.org_project_id AS projectId FROM org_sites s JOIN org_projects p ON p.id = s.org_project_id WHERE p.company_id = ? AND s.deleted_at IS NULL AND s.status = 'ACTIVE' ORDER BY s.code").all(actor.companyId).filter((s) => okp(s.projectId)),
        activities: db.prepare('SELECT a.id, a.code, a.name, s.org_project_id AS projectId FROM plan_activities a JOIN plan_schedules s ON s.id = a.schedule_id WHERE a.company_id = ? AND a.deleted_at IS NULL ORDER BY a.code LIMIT 800').all(actor.companyId).filter((a) => okp(a.projectId)), priorities: Object.entries(PRIORITY).map(([id, label]) => ({ id, label })) };
